import app from 'flarum/forum/app';
import extractText from 'flarum/common/utils/extractText';
export const t = (key, params = {}) => app.translator.trans(`ernestdefoe-mural.forum.${key}`, params);

/** Server clock minus ours: cooldowns count down by the server's time. */
let skew = 0;
export function setSkew(serverNow) {
  if (serverNow) skew = Date.parse(serverNow) - Date.now();
}
export const now = () => Date.now() + skew;
export function errorText(error) {
  const code = error?.response?.errors?.[0]?.code;
  const known = ['mural_banned', 'mural_cooldown', 'mural_slow_down', 'mural_season_over', 'mural_bad_tile', 'mural_confirm_email', 'mural_no_such_user', 'mural_rollback_needs_filter', 'mural_cannot_ban', 'mural_not_found'];
  return extractText(known.includes(code) ? t(`errors.${code.slice(6)}`) : app.translator.trans('core.lib.error.generic_message'));
}
export function call(method, path, data, quiet = false) {
  const url = app.forum.attribute('apiUrl') + '/mural' + path;
  const query = method === 'GET' && data ? '?' + new URLSearchParams(data).toString() : '';
  return app.request({
    method,
    url: url + query,
    body: method === 'GET' ? undefined : data,
    background: method === 'GET',
    errorHandler: error => {
      if (!quiet) app.alerts.show({
        type: 'error'
      }, errorText(error));
      throw error;
    }
  });
}

/** Members arrive as compact rows; the store lets avatar() and username() draw them the usual way. */
export function person(row) {
  if (!row) return null;
  return app.store.pushObject({
    type: 'users',
    id: String(row.id),
    attributes: {
      username: row.username,
      displayName: row.displayName,
      slug: row.slug,
      avatarUrl: row.avatarUrl
    }
  });
}

/** The picture's bytes: raw deflate in base64, inflated by the browser. */
export async function inflate(b64, raw = false) {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  if (raw) return bytes;
  const stream = new Blob([bytes]).stream().pipeThrough(new window.DecompressionStream('deflate-raw'));
  return new Uint8Array(await new Response(stream).arrayBuffer());
}
export const canInflate = () => typeof window.DecompressionStream === 'function';

/** Palette as little-endian RGBA words, ready for an ImageData's Uint32 view. */
export function paletteWords(palette) {
  const words = new Uint32Array(palette.length);
  palette.forEach((hex, i) => {
    const n = parseInt(hex.slice(1), 16);
    words[i] = 0xff << 24 | (n & 0xff) << 16 | n & 0xff00 | n >> 16 & 0xff;
  });
  return words;
}
export function seasonName(season) {
  return extractText(season.title || t('season.name', {
    number: season.number
  }));
}
export const fmt = n => n.toLocaleString(app.translator.getLocale?.() || undefined);