import app from 'flarum/forum/app';
import Link from 'flarum/common/components/Link';
import Avatar from 'flarum/common/components/Avatar';
import username from 'flarum/common/helpers/username';
import humanTime from 'flarum/common/helpers/humanTime';
import extractText from 'flarum/common/utils/extractText';
import { fmt, person, t } from '../api';
/** A Mithril component from a function of its attrs (a bare function tag is a closure component to Mithril, not a render function). */
function fc(render) {
  return () => ({
    view: vnode => render(vnode.attrs)
  });
}

/** A member: avatar and name, linking to their profile. */
export const Person = fc(({
  row,
  size
}) => {
  const user = person(row);
  if (!user) return m("span", {
    className: "MuralPerson MuralPerson--gone"
  }, t('tile.deleted'));
  return m(Link, {
    className: "MuralPerson",
    href: app.route.user(user)
  }, m(Avatar, {
    user: user,
    className: size === 'small' ? 'Avatar--small' : ''
  }), m("span", {
    className: "MuralPerson-name"
  }, username(user)));
});
export const Time = fc(({
  at
}) => humanTime(new Date(at)));

/** The top painters, with a bar for each one's share of the leader's count. */
export const Leaders = fc(({
  rows
}) => {
  if (!rows.length) return m("p", {
    className: "MuralEmpty"
  }, t('stats.no_painters'));
  const best = rows[0].tiles || 1;
  return m("ol", {
    className: "MuralLeaders"
  }, rows.map((row, i) => m("li", {
    className: "MuralLeaders-row",
    style: {
      '--share': `${Math.max(4, row.tiles / best * 100)}%`
    }
  }, m("span", {
    className: `MuralLeaders-place MuralLeaders-place--${i + 1}`
  }, i + 1), m(Person, {
    row: row.user,
    size: "small"
  }), m("span", {
    className: "MuralLeaders-count"
  }, fmt(row.tiles)))));
});

/** 24 hourly bars, oldest on the left. */
export const Hours = fc(({
  stats
}) => {
  const max = Math.max(1, ...stats.hours);
  const from = Date.parse(stats.hoursFrom);
  const label = h => new Date(from + h * 3600000).toLocaleTimeString([], {
    hour: 'numeric'
  });
  return m("div", {
    className: "MuralHours"
  }, m("div", {
    className: "MuralHours-bars",
    role: "img",
    "aria-label": extractText(t('stats.hours_label', {
      count: stats.last24
    }))
  }, stats.hours.map((n, h) => m("span", {
    className: "MuralHours-bar",
    style: {
      height: `${n ? Math.max(6, n / max * 100) : 2}%`
    },
    title: `${label(h)} · ${fmt(n)}`
  }))), m("div", {
    className: "MuralHours-axis"
  }, m("span", null, label(0)), m("span", null, label(12)), m("span", null, t('stats.now'))));
});
/** "Who painted this": a small card by the pointer, kept inside the stage. */
export const HoverCard = fc(({
  hover,
  viewer,
  palette
}) => {
  if (!hover || !viewer) return null;
  const box = viewer.canvas.getBoundingClientRect();
  const left = Math.min(box.width - 230, Math.max(8, hover.x - box.left + 16));
  const top = Math.min(box.height - 70, Math.max(8, hover.y - box.top + 16));
  return m("div", {
    className: "MuralHover",
    style: {
      left: `${left}px`,
      top: `${top}px`
    },
    role: "status"
  }, m("span", {
    className: "MuralSwatch",
    style: {
      background: palette[viewer.colourAt(hover.tile[0], hover.tile[1])]
    }
  }), m("span", {
    className: "MuralHover-text"
  }, m("span", {
    className: "MuralHover-where"
  }, hover.tile[0], ", ", hover.tile[1]), hover.info === undefined ? m("span", {
    className: "MuralHover-who"
  }, "\u2026") : hover.info ? m("span", {
    className: "MuralHover-who"
  }, m(Person, {
    row: hover.info.user,
    size: "small"
  }), " ", m(Time, {
    at: hover.info.placedAt
  })) : m("span", {
    className: "MuralHover-who"
  }, t('tile.blank'))));
});
flarum.reg.add('ernestdefoe-mural', 'forum/components/parts', { Person: Person,Time: Time,Leaders: Leaders,Hours: Hours,HoverCard: HoverCard, });